#pragma once

#include <QString>

// A single asynchronous manual-WiFi interaction may own each host-side event
// stream. Requests are generated by the requesting facade and projected back
// with events, so other browser tabs cannot act on its dialog state.
class ManualWifiRequestOwner final
{
public:
    bool acquire(const QString& requestId)
    {
        if (requestId.isEmpty() || !m_requestId.isEmpty())
            return false;
        m_requestId = requestId;
        return true;
    }

    QString requestId() const { return m_requestId; }
    bool owns(const QString& requestId) const
    {
        return !requestId.isEmpty() && m_requestId == requestId;
    }

    bool release(const QString& requestId)
    {
        if (!owns(requestId))
            return false;
        m_requestId.clear();
        return true;
    }

    static bool transfer(ManualWifiRequestOwner& from, const QString& fromId,
                         ManualWifiRequestOwner& to, const QString& toId)
    {
        if (!from.owns(fromId) || toId.isEmpty() || !to.m_requestId.isEmpty())
            return false;
        from.release(fromId);
        return to.acquire(toId);
    }

    void clear() { m_requestId.clear(); }

private:
    QString m_requestId;
};
